@@ -0,0 +1,13 @@
+import { createEventCard } from './event-card.js';
+
+// Projects each event (validating it) and orders the results by startsAt; ties keep input order.
+export function sortByStartsAt(events, project) {
+  return events
+    .map((event) => ({ value: project(event), time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time)
+    .map(({ value }) => value);
+}
+
+export function buildAgenda(events) {
+  return sortByStartsAt(events, createEventCard);
+}

